ated\":\"true\",\"Preliminary\":false,\"IsBackend\":false},{\"Name\":\"GetCollection\",\"Summary\":\"Deprecated. Use GetTagged instead.\",\"Browsable\":true,\"Deprecated\":\"true\",\"Preliminary\":false,\"IsBackend\":false},{\"Name\":\"GetTagged\",\"Summary\":\"Returns an array of all of the instances in the data model which have the given tag.\",\"Browsable\":true,\"Deprecated\":false,\"Preliminary\":false,\"IsBackend\":false},{\"Name\":\"AddTag\",\"Summary\":\"Adds a tag to an instance.\",\"Browsable\":true,\"Deprecated\":false,\"Preliminary\":false,\"IsBackend\":false},{\"Name\":\"RemoveTag\",\"Summary\":\"Removes a tag to an instance.\",\"Browsable\":true,\"Deprecated\":false,\"Preliminary\":false,\"IsBackend\":false},{\"Name\":\"GetTags\",\"Summary\":\"Returns a list of all the collections that an instance belongs to.\",\"Browsable\":true,\"Deprecated\":false,\"Preliminary\":false,\"IsBackend\":false},{\"Name\":\"HasTag\",\"Summary\":\"Returns whether the given instance has the given tag.\",\"Browsable\":true,\"Deprecated\":false,\"Preliminary\":false,\"IsBackend\":false},{\"Name\":\"GetInstanceAddedSignal\",\"Summary\":\"Returns a signal that fires when the given tag either has a new instance with that tag added to the data model or that tag is assigned to an instance within the data model.\",\"Browsable\":true,\"Deprecated\":false,\"Preliminary\":false,\"IsBackend\":false},{\"Name\":\"GetInstanceRemovedSignal\",\"Summary\":\"Returns a signal that fires when the given tag either has an instance with that tag removed from the data model or that tag is removed from an instance within the data model.\",\"Browsable\":true,\"Deprecated\":false,\"Preliminary\":false,\"IsBackend\":false}],\"Deprecated\":false,\"Preliminary\":false,\"IsBackend\":false},{\"Name\":\"JointsService\",\"Summary\":\"\",\"ExplorerOrder\":0,\"ExplorerImageIndex\":0,\"Browsable\":true,\"PreferredParent\":\"\",\"Members\":[],\"Deprecated\":false,\"Preliminary\":false,\"IsBackend\":false},{\"Nam